void LensFlareTask_80014CCC(int* flags, void* buf)
{
    EffectObj* obj = buf;
    short size[2];
    short col[4];
    int dir[3];
    int pos[3];
    int span[3];
    int pos2[3];
    unsigned char rgb[4];
    short flareSize[2];
    int idx;
    EffectSprite* e1;
    EffectSprite* e2;
    EffectSpriteFrame* sp;
    int dot;
    Vec3i* camPos;
    Vec3i* lookAt;

    obj->field_4++;
    PushMatrix();
    ApplyMatrix(&obj->targetBoneMatrices_2C[obj->bone_98], (SVECTOR*)&obj->offset_24, (VECTOR*)obj->pos_44);
    PopMatrix();
    obj->pos_44[0] = obj->targetBonePos_20[obj->bone_98 * 3 + 0] + obj->pos_44[0];
    obj->pos_44[1] = obj->targetBonePos_20[obj->bone_98 * 3 + 1] + obj->pos_44[1];
    obj->pos_44[2] = obj->targetBonePos_20[obj->bone_98 * 3 + 2] + obj->pos_44[2];
    obj->pos_44[0] = obj->targetPos_1C[0] + obj->pos_44[0];
    obj->pos_44[1] = obj->targetPos_1C[1] + obj->pos_44[1];
    obj->pos_44[2] = obj->targetPos_1C[2] + obj->pos_44[2];
    e1 = &effectFile_80091BD0.sprites_20[FindEffectIndex_80020F00(&effectFile_80091BD0, 0, 0x25)];
    idx = FindEffectIndex_80020F00(&effectFile_80091BD0, 0, 0x26);
    e2 = &effectFile_80091BD0.sprites_20[idx];
    sp = *e1->frames_8;
    size[0] = sp->size_C[0] * (sinTable_80084540[(obj->field_4 << 6) & 0xFC0] / 4 + 0x1000) / 4096;
    size[1] = sp->size_C[1] * (sinTable_80084540[(obj->field_4 << 6) & 0xFC0] / 4 + 0x1000) / 4096;
    col[0] = sp->pos_10[0];
    col[1] = sp->pos_10[1];
    col[2] = sp->pos_10[2];
    col[3] = obj->field_4 * 32;
    DrawRotSprite_80044010(&e1->poly_C, obj->pos_44, &obj->rot_80, &sp->u_0, &sp->w_4, &sp->pivotX_8, size, col, sp->rgb_18, 2, 0x30,
                 pOT_8008D690);
    camPos = &cameraState_8008D4F0.eye_14;
    rgb[0] = sp->rgb_18[0] >> 3;
    rgb[1] = sp->rgb_18[1] >> 3;
    rgb[2] = sp->rgb_18[1] >> 3;
    lookAt = &cameraState_8008D4F0.lookAt_20;
    pos[0] = obj->pos_44[0] - camPos->x;
    pos[1] = obj->pos_44[1] - camPos->y;
    pos[2] = obj->pos_44[2] - camPos->z;
    dir[0] = lookAt->x - camPos->x;
    dir[1] = lookAt->y - camPos->y;
    dir[2] = lookAt->z - camPos->z;
    VectorNormal((VECTOR*)dir, (VECTOR*)dir);
    dot = (dir[0] * pos[0] + dir[1] * pos[1] + dir[2] * pos[2]) / 4096;
    pos[0] = cameraState_8008D4F0.eye_14.x + dir[0] * dot / 8192;
    pos[1] = cameraState_8008D4F0.eye_14.y + dir[1] * dot / 8192;
    pos[2] = cameraState_8008D4F0.eye_14.z + dir[2] * dot / 8192;
    if (cameraState_8008D4F0.geomScreen_2E < dot)
    {
        flareSize[0] = size[0] / 4;
        flareSize[1] = size[1] / 4;
        DrawRotSprite_80044010(&e2->poly_C, pos, &obj->rot_80, &sp->u_0, &sp->w_4, &sp->pivotX_8, flareSize, col, rgb, 0, 0x30,
                     pOT_8008D690);
    }
    span[0] = obj->pos_44[0] - pos[0];
    span[1] = obj->pos_44[1] - pos[1];
    span[2] = obj->pos_44[2] - pos[2];
    if (cameraState_8008D4F0.geomScreen_2E * 4 / 3 < dot)
    {
        pos2[0] = pos[0] + span[0] / 2;
        pos2[1] = pos[1] + span[1] / 2;
        pos2[2] = pos[2] + span[2] / 2;
        flareSize[0] = size[0];
        flareSize[1] = size[1];
        DrawRotSprite_80044010(&e2->poly_C, pos2, &obj->rot_80, &sp->u_0, &sp->w_4, &sp->pivotX_8, flareSize, col, rgb, 0, 0x30,
                     pOT_8008D690);
    }
    if (cameraState_8008D4F0.geomScreen_2E * 2 < dot)
    {
        pos2[0] = pos[0] - span[0] / 2;
        pos2[1] = pos[1] - span[1] / 2;
        pos2[2] = pos[2] - span[2] / 2;
        flareSize[0] = size[0] / 2;
        flareSize[1] = size[1] / 2;
        DrawRotSprite_80044010(&e2->poly_C, pos2, &obj->rot_80, &sp->u_0, &sp->w_4, &sp->pivotX_8, flareSize, col, rgb, 0, 0x30,
                     pOT_8008D690);
    }
    if (cameraState_8008D4F0.geomScreen_2E * 4 / 3 < dot)
    {
        pos2[0] = pos[0] - span[0] / 4;
        pos2[1] = pos[1] - span[1] / 4;
        pos2[2] = pos[2] - span[2] / 4;
        flareSize[0] = size[0] * 2;
        flareSize[1] = size[1] * 2;
        DrawRotSprite_80044010(&e2->poly_C, pos2, &obj->rot_80, &sp->u_0, &sp->w_4, &sp->pivotX_8, flareSize, col, rgb, 0, 0x30,
                     pOT_8008D690);
    }
    if (effectOutcomeFlag_8008D780[0] == 1)
    {
        *flags = (*flags & ~1) | 0x8000;
    }
}
